INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「温故知新」', NULL, '["新しい知識だけを追い求めること","昔のことを学び、そこから新しい知見を得ること","古い習慣をすべて捨て去ること","新旧の知識を比較して優劣をつけること","過去の失敗を繰り返さないよう戒めること"]', 1, '["「故きを温ねて新しきを知る」という孔子の言葉に由来し、昔のことをよく学び、そこから新たな知識や見解を得ることを意味する。単に古いものを守るのではなく、そこから新しい発見を導く点がポイントである。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「臥薪嘗胆」', NULL, '["目的を達成するために苦労や困難を耐え忍ぶこと","何もせずに時が過ぎるのを待つこと","他人の成功をねたみ、足を引っ張ること","一時の快楽に身をゆだねること","困難を避けて安全な道を選ぶこと"]', 0, '["薪の上に寝て苦い胆をなめるという中国の故事に由来し、目的を達成するために、あえて苦しい環境に身を置き、耐え忍ぶことを意味する。復讐や雪辱を期して長期間苦労を重ねる場面で使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「呉越同舟」', NULL, '["仲の良い者同士が協力し合うこと","敵対する者同士が同じ場所や状況に置かれること","多くの人が同じ意見にまとまること","立場の異なる者が互いに争い続けること","見知らぬ者同士が偶然出会うこと"]', 1, '["敵対関係にあった呉と越の人が同じ船に乗り合わせたという故事に由来し、仲の悪い者同士が同じ場所や状況に居合わせること、あるいは共通の困難に直面して協力せざるを得ない状況を意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「塞翁が馬」(人間万事塞翁が馬)', NULL, '["人生の幸不幸は予測できないものであること","馬は人間にとって最も身近な動物であること","災いは必ず自分の努力で防げること","幸運は一度手にすれば永遠に続くこと","老人の言うことには従うべきであること"]', 0, '["国境の塞に住む老人の馬にまつわる故事に由来し、人生における幸福や不幸は予測しがたく、一見不運に思えることが後に幸運につながることもあれば、その逆もあるということを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「蛇足」', NULL, '["物事の仕上げに欠かせない最後の一手","なくてもよい、むしろ余計な付け足し","見た目だけを飾り立てること","本筋から外れた話題に脱線すること","失敗を隠すために取り繕うこと"]', 1, '["ヘビの絵を描く競争で、足を描き足してしまい負けたという故事に由来し、なくてもよい、あるいはあることでかえって全体を損なう余計な付け足しを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「五十歩百歩」', NULL, '["程度の差はあっても本質的には大差がないこと","わずかな差が最終的に大きな結果の違いを生むこと","一歩一歩着実に前進すること","目標達成まで長い道のりがあること","互いに譲り合って争いを避けること"]', 0, '["戦場で五十歩逃げた者が百歩逃げた者を臆病だと笑ったという故事に由来し、多少の違いはあっても、本質的には大した差がないことを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「蛍雪の功」', NULL, '["自然の美しさを愛でながら過ごす日々","貧しく苦しい環境のなかで学問に励んだ成果","短期間で成果を出す優れた才能","他人に頼らず独学で成功すること","季節の移ろいを感じながら生活すること"]', 1, '["貧しさのために灯火用の油が買えず、蛍の光や雪明かりで書を読んで勉学に励んだという故事に由来し、苦労を重ねながら学問に励んだ成果を意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「一石二鳥」', NULL, '["一つの行動で二つの利益を同時に得ること","一つの過ちが二つの災いを招くこと","二つのことを同時に行い、両方とも中途半端に終わること","一つの目標に向けて二人で協力すること","一つの成功が次々と幸運を呼び込むこと"]', 0, '["一つの石を投げて二羽の鳥を落とすという発想に由来し、一つの行動によって同時に二つの利益や成果を得ることを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「大器晩成」', NULL, '["大きな器は壊れやすいということ","優れた人物は若いうちから頭角を現すこと","優れた才能を持つ人物は、大成するまでに時間がかかること","器の大きさで人の価値が決まること","晩年になってから道具を揃えても遅いということ"]', 2, '["大きな器ほど作り上げるのに時間がかかることになぞらえ、真に優れた才能を持つ人物は、若いうちにはなかなか頭角を現さず、時間をかけて後年になって成功を収めるものだという考え方を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「傍若無人」', NULL, '["周囲を気遣いすぎて自分の意見を言えないこと","他人の目を気にせず、勝手気ままにふるまうこと","周囲の状況を冷静に観察してから行動すること","誰にも頼らず一人で物事を成し遂げること","大勢の前で緊張してうまく話せないこと"]', 1, '["「傍らに人無きが若し(そばに人がいないかのように)」という意味から、周囲の人のことを気にかけず、自分勝手にふるまうことを意味する。批判的なニュアンスで使われることが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「面目躍如」', NULL, '["評判通りの活躍をして、その真価を存分に発揮すること","恥をかいて人前に出られなくなること","自分の顔つきや表情を偽ること","期待を裏切り、周囲を失望させること","目立たないように控えめにふるまうこと"]', 0, '["「面目」は世間からの評価や体面を、「躍如」は生き生きとした様子を表し、その人本来の評価にふさわしい活躍ぶりが、生き生きと表れているさまを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「空前絶後」', NULL, '["これまでに一度も例がなく、今後も起こらないと思われるほど珍しいこと","前触れもなく、突然物事が起こること","物事の始まりと終わりがはっきりしていること","過去の出来事をすべて忘れ去ってしまうこと","前後の文脈がつながらず、意味が通じないこと"]', 0, '["「空前」は以前に例がないこと、「絶後」は今後も起こりそうにないことを意味し、両者を合わせて、過去にも未来にも比類がないほど非常に珍しいことを表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「千載一遇」', NULL, '["千人に一人しかいない優れた人材のこと","めったに巡り合えない、またとない好機のこと","千年に一度起こる大きな災害のこと","何度失敗しても諦めずに挑戦し続けること","多くの人が一斉に同じ行動をとること"]', 1, '["「千載」は千年、「一遇」は一度出会うことを意味し、千年に一度しか巡り合えないほど、めったにない絶好の機会を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「竜頭蛇尾」', NULL, '["最初は勢いが盛んだが、終わりに近づくにつれて勢いが衰えること","始めから終わりまで一貫して勢いを保ち続けること","見た目は立派だが中身が伴わないこと","小さな出来事が大きな結果を招くこと","二つの異なるものが一つに合わさること"]', 0, '["頭は竜のように立派だが、尾は蛇のように貧弱であることから、物事の始めは勢いが盛んであるものの、終わりに近づくにつれて次第に勢いが衰えていくことを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「朝三暮四」', NULL, '["朝と夜で全く異なる仕事をすること","目先の違いにとらわれ、結果が同じであることに気づかないこと","一日のうちに何度も予定を変更すること","朝早くから夜遅くまで休みなく働くこと","過去の言動を反省し、改めること"]', 1, '["猿にえさを「朝三つ夕方四つ」から「朝四つ夕方三つ」に変えると伝えたところ、猿が喜んだという故事に由来し、結果は同じであるにもかかわらず、目先の違いにとらわれて一喜一憂することを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「四面楚歌」', NULL, '["四方八方から敵に囲まれ、味方がいない状況","多くの人から歌や踊りで歓迎されること","四季の移り変わりを楽しむこと","四つの方角すべてに詳しい知識を持つこと","多くの選択肢のなかから最善のものを選ぶこと"]', 0, '["楚の武将が敵軍に包囲され、四方から楚の歌が聞こえてきたことで、味方がすでに降伏したと悟った故事に由来し、周囲を敵に囲まれ、孤立無援の状況に陥ることを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「玉石混淆」', NULL, '["優れたものと劣ったものが入り混じっていること","すべてが優れた品質で統一されていること","宝石のように美しいものだけを集めること","石を積み重ねて丈夫な建物を作ること","異なる文化が融合して新しいものを生み出すこと"]', 0, '["美しい玉と、ただの石とが入り混じっている様子から、優れたものとつまらないものとが、区別されないまま入り混じっている状態を意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「唯我独尊」', NULL, '["自分こそが世界で最も優れているとうぬぼれること","自分の意見を持たず、他人に従うこと","誰にも頼らず、一人で静かに暮らすこと","自分の欠点を素直に認めること","他人の意見を尊重し、譲り合うこと"]', 0, '["本来は釈迦の誕生にまつわる言葉に由来するが、一般には、自分だけが優れており尊いのだと考え、うぬぼれる態度を指す、批判的な意味で使われることが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「有為転変」', NULL, '["世の中のすべての物事は絶えず移り変わるということ","努力すれば必ず物事は好転するということ","一度決めたことは変えるべきではないということ","物事は常に一定の法則に従って進むということ","失敗を重ねることで有能な人材になるということ"]', 0, '["仏教の考え方に由来し、この世のあらゆる物事は常に移り変わり、永遠不変のものは何一つないということを意味する。人生の無常観を表す言葉として使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「因果応報」', NULL, '["良い行いにも悪い行いにも、それにふさわしい報いが返ってくること","原因のない結果は決して存在しないこと","一度の失敗が取り返しのつかない結果を招くこと","他人の行いの報いを自分が受けること","良い結果は必ず悪い結果に転じること"]', 0, '["仏教の考え方に由来し、人の行いには必ずそれに応じた結果が返ってくるということを意味する。特に、悪い行いには悪い報いが返ってくるという意味で使われることが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「会者定離」', NULL, '["出会った者は必ずいつか別れる運命にあるということ","多くの人と出会うことが人生を豊かにするということ","一度別れた者とは二度と会えないということ","会議で決まったことは必ず実行すべきだということ","人との出会いは偶然によってのみ生まれるということ"]', 0, '["仏教の考え方に由来し、この世で出会った人とは、いずれ必ず別れる時が来るという、人生の無常を表す言葉である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「一期一会」', NULL, '["一生に一度しか会えない有名人のこと","生涯に一度だけ許される重大な失敗のこと","一度の出会いを、生涯にただ一度の機会として大切にする心構え","一年に一度だけ開催される特別な行事のこと","一つの目標に向かって一生をかけて取り組むこと"]', 2, '["茶道の心得に由来し、目の前の出会いは二度と繰り返されない、一生に一度限りのものであると心得て、その一瞬一瞬を大切にするべきだという考え方を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「疑心暗鬼」', NULL, '["一度信じたことは、何があっても疑わないこと","疑いの心を持つと、何でもないことまで恐ろしく感じられること","暗闇のなかで物事を冷静に判断すること","他人の秘密を暴こうとすること","疑わしい人物をあらかじめ排除しておくこと"]', 1, '["「疑心暗鬼を生ず」という言葉に由来し、疑う心があると、何でもないものまで恐ろしいものに見えてしまう、ということを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「起死回生」', NULL, '["絶望的な状況を、一気に良い方向へ立て直すこと","死者を弔い、その霊を慰めること","過去の失敗を何度も思い返すこと","生死を分けるほどの重大な決断を下すこと","病気にかかった人を、時間をかけて回復させること"]', 0, '["死にかけている者を生き返らせるという意味から、絶望的で危機的な状況を、劇的な方法で一気に良い方向へ立て直すことを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「捲土重来」', NULL, '["一度失敗した者が、勢いを盛り返して再び挑むこと","土地を耕し直し、一から農業を始めること","一度の勝利に満足せず、さらに慢心すること","過去の栄光にすがり続けること","同じ失敗を何度も繰り返すこと"]', 0, '["土煙を巻き上げて再びやって来るという意味から、一度敗れた者や失敗した者が、勢いを盛り返して再び挑戦することを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「画竜点睛」', NULL, '["物事を最後に仕上げる、最も肝心な仕上げのこと","絵を描く技術がまったく未熟であること","目立たない部分にまで手を抜かず作業すること","多くの作品のなかから優れたものを選び出すこと","計画の最初の段階でつまずくこと"]', 0, '["竜の絵に睛(ひとみ)を描き入れたところ、その竜が天に昇ったという故事に由来し、物事を完成させるための、最後の最も肝心な仕上げを意味する。「画竜点睛を欠く」の形で、肝心な仕上げが欠けている状態を表す使い方も多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「単刀直入」', NULL, '["遠回しな言い方で、相手の反応をうかがうこと","前置きなしに、いきなり本題や要点に入ること","一人で多くの敵に立ち向かうこと","一つの道具だけで複数の作業をこなすこと","単純な言葉で複雑な内容を説明すること"]', 1, '["一本の刀を持って、ただ一人で敵陣に切り込むという意味から、前置きや遠回しな言い方をせず、いきなり話の本題や要点に入ることを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「千差万別」', NULL, '["多くのものが、それぞれに異なる特徴や性質を持っていること","多くの選択肢のなかから一つだけを選ぶこと","千人の人が全く同じ意見を持つこと","わずかな違いが、大きな結果の差につながること","多くの物事が一つの結論に収束していくこと"]', 0, '["多くのものが、それぞれさまざまに異なっていることを意味する。人の考え方や物事のあり方が、実に多様であることを表す際に使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「意気投合」', NULL, '["互いの考えや気持ちがぴったりと一致すること","議論が対立し、まとまらないこと","一時的な勢いに任せて行動すること","相手の意見に無理やり合わせること","互いに競い合って実力を高め合うこと"]', 0, '["互いの気持ちや考え方がぴったりと一致し、たちまち親しくなることを意味する。初対面の相手とすぐに打ち解ける場面などで使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「我田引水」', NULL, '["自分の利益になるように、都合よく物事を進めたり解釈したりすること","他人のために、自分の利益を犠牲にすること","争いを避けて、中立の立場を保つこと","自然の恵みに感謝し、大切にすること","自分の田畑を他人に譲り渡すこと"]', 0, '["自分の田んぼにだけ水を引き入れるという意味から、自分の利益になるように、物事を都合よく進めたり、解釈したりすることを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「花鳥風月」', NULL, '["自然界の美しい風物、風雅な趣のこと","季節ごとの農作業のこと","華やかな都市の夜景のこと","人間関係における駆け引きのこと","短い期間で移り変わる流行のこと"]', 0, '["花や鳥、風、月といった、自然界に見られる美しい風物を指し、それらを愛でる風雅な趣を表す言葉として使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「有言実行」', NULL, '["口に出したことを、責任を持って実際に行うこと","何も言わずに黙って行動すること","言葉だけが立派で、行動が伴わないこと","他人の言葉を信じて行動すること","言い訳をしながら物事を進めること"]', 0, '["自分が口に出して宣言したことを、実際に行動に移して実現することを意味する。「不言実行」に対して、あえて宣言してから実行に移す姿勢を表す言葉として使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「大同小異」', NULL, '["大まかな部分は同じで、細かい点にわずかな違いがあること","大きな違いはあるが、根本は共通していること","立場によって、全く異なる評価がなされること","小さな出来事が、大きな結果を引き起こすこと","多数派の意見と少数派の意見が対立すること"]', 0, '["大きなところではほぼ同じであり、細部にわずかな違いがあるだけであることを意味する。複数の物事を比較して、本質的にはあまり差がないと述べる際に使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「一朝一夕」', NULL, '["ごく短い期間のこと","一年を通して変わらないこと","毎日決まった時間に行う習慣のこと","一生をかけて成し遂げるべきこと","朝と夜とで全く異なる様子を見せること"]', 0, '["「一朝」も「一夕」も、ひと朝、ひと晩というごく短い時間を意味し、両者を合わせて、わずかな期間を表す。「一朝一夕にはいかない」のように、打ち消しの形で使われることが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「半信半疑」', NULL, '["半分は信じ、半分は疑わしく思う、判断に迷う状態","相手の言葉をすべて信じ切ること","何事も最初から疑ってかかる態度","信じていたことが裏切られ、疑いに変わること","二人のうち一人だけが真実を知っていること"]', 0, '["話や情報の一部は信じられるものの、一部は疑わしく感じられ、本当かどうか判断がつきかねる状態を意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「質実剛健」', NULL, '["飾り気がなく誠実で、心身ともにたくましいこと","見た目が華やかで美しいこと","物事を慎重に進め、決して冒険をしないこと","知識が豊富で、学問に優れていること","他人の意見に流されやすい性格のこと"]', 0, '["「質実」は飾り気がなく誠実なこと、「剛健」は心身がたくましく強いことを意味し、両者を合わせて、飾らず真面目で、たくましい気風を表す言葉として使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「泰然自若」', NULL, '["落ち着き払っていて、何事にも動じないさま","自信がなく、いつもおどおどしているさま","自分の意見を持たず、周囲に流されるさま","興奮して、感情のままに行動するさま","一人でいることを好み、他人と関わらないさま"]', 0, '["「泰然」はゆったりと落ち着いているさま、「自若」は普段と変わらず平然としているさまを意味し、両者を合わせて、どのような事態に直面しても、落ち着き払って動じない様子を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「付和雷同」', NULL, '["自分の考えを持たず、安易に他人の意見に同調すること","多くの人と協力して一つの目標を達成すること","雷のような大きな声で自分の意見を主張すること","天候の変化に合わせて、計画を柔軟に変えること","互いに反対の立場から議論を戦わせること"]', 0, '["しっかりとした自分の考えを持たず、他人の意見にわけもなく賛同し、行動を合わせることを意味する。批判的なニュアンスで使われることが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「用意周到」', NULL, '["準備が細部にまで行き届いていて、抜かりがないこと","準備を怠り、行き当たりばったりで物事を進めること","多くの人が協力して準備を進めること","準備に時間をかけすぎて、機会を逃すこと","必要最低限の準備だけで物事に臨むこと"]', 0, '["物事を行う前の準備が、細部に至るまで行き届いており、抜け目がないさまを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「温厚篤実」', NULL, '["性格が穏やかで、誠実であること","感情の起伏が激しく、扱いにくい性格であること","物事に対して無関心で、冷淡であること","自分の利益を優先し、他人を顧みないこと","表向きは穏やかだが、内心では計算高いこと"]', 0, '["「温厚」は性格が穏やかで情け深いこと、「篤実」は人情に厚く誠実であることを意味し、両者を合わせて、穏やかで誠実な人柄を表す言葉として使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「切磋琢磨」', NULL, '["互いに励まし合い、競い合いながら向上すること","一人で黙々と努力を積み重ねること","他人の欠点を厳しく指摘し合うこと","争いを避け、互いに譲り合うこと","過去の失敗を厳しく反省すること"]', 0, '["骨や象牙、玉などを、切り、磨いて仕上げていく工程になぞらえ、仲間同士が互いに励まし合い、競い合いながら、学問や技術を高め合っていくことを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「森羅万象」', NULL, '["宇宙に存在する、ありとあらゆる物事のこと","森のなかにだけ生息する、珍しい生き物のこと","人間が作り出した、あらゆる文化や制度のこと","季節ごとに移り変わる自然現象のこと","目に見えない、抽象的な概念のみを指す言葉"]', 0, '["宇宙に存在する、ありとあらゆる現象や事物を意味する言葉であり、自然物に限らず、この世に存在するすべてのものを指して使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「変幻自在」', NULL, '["自分の思いのままに、姿や形を自由自在に変えられること","一度決めた方針を、決して変えないこと","常に一定の姿を保ち続けること","他人の変化に、そのまま合わせて行動すること","予測できない出来事に、動揺してしまうこと"]', 0, '["「変幻」は姿を変えて現れたり消えたりすること、「自在」は思いのままであることを意味し、両者を合わせて、自分の思うままに、姿や形、対応を自由自在に変えられることを表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「波瀾万丈」', NULL, '["物事の展開が、変化に富み、劇的であること","穏やかで、何の変化も起こらないこと","海や川の波が、常に一定であること","一度の失敗で、すべてを失ってしまうこと","長い時間をかけて、着実に成果を積み重ねること"]', 0, '["「波瀾」は物事の変化や紛糾を、「万丈」は非常に高い、大きいことを意味し、両者を合わせて、物事の展開が非常に激しく変化に富み、劇的であることを表す。人の生涯や物語の筋書きを形容する際によく使われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '四字熟語', NULL, '次の四字熟語・故事成語の意味として、最も適切なものはどれか。

「二律背反」', NULL, '["同等に正しいと思われる二つの原理や主張が、互いに矛盾し両立しないこと","二つの法律が、全く同じ内容を定めていること","二人の人物が、常に同じ意見を持つこと","一つの規則を、二通りに解釈できること","二つの選択肢のうち、どちらを選んでも同じ結果になること"]', 0, '["それぞれに根拠があり、同等に成り立つと思われる二つの原理や主張が、互いに矛盾し、両立しない関係にあることを意味する。哲学の分野で使われることの多い語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 四字熟語）');
